inline constexpr char blur_frag_msl[] =
R"jvkmsl(#include <metal_stdlib>
#include <simd/simd.h>

using namespace metal;

struct JvkConstants
{
    float2 viewportSize;
    float2 direction;
    float radius;
};

struct main0_out
{
    float4 outColor [[color(0)]];
};

struct main0_in
{
    float2 fragUV [[user(locn0)]];
};

fragment main0_out main0(main0_in in [[stage_in]], constant JvkConstants& pc [[buffer(24)]], texture2d<float> srcTexture [[texture(0)]], sampler srcSampler [[sampler(8)]])
{
    main0_out out = {};
    float2 texelSize = float2(1.0) / pc.viewportSize;
    if (pc.radius <= 0.5)
    {
        out.outColor = srcTexture.sample(srcSampler, in.fragUV);
        return out;
    }
    float sigma = pc.radius * 0.5;
    float twoS2 = (2.0 * sigma) * sigma;
    int N = int(ceil(pc.radius));
    float4 color = srcTexture.sample(srcSampler, in.fragUV);
    float totalWeight = 1.0;
    float _109;
    for (int p = 0; p < 4096; p++)
    {
        int i1 = (2 * p) + 1;
        if (i1 > N)
        {
            break;
        }
        int i2 = i1 + 1;
        float w1 = exp((-float(i1 * i1)) / twoS2);
        if (i2 <= N)
        {
            _109 = exp((-float(i2 * i2)) / twoS2);
        }
        else
        {
            _109 = 0.0;
        }
        float w2 = _109;
        float w = w1 + w2;
        float o = ((float(i1) * w1) + (float(i2) * w2)) / w;
        float2 off = (pc.direction * o) * texelSize;
        color += (srcTexture.sample(srcSampler, (in.fragUV + off)) * w);
        color += (srcTexture.sample(srcSampler, (in.fragUV - off)) * w);
        totalWeight += (2.0 * w);
    }
    out.outColor = color / float4(totalWeight);
    return out;
}

)jvkmsl";
#endif

